<template>
  <Toaster
    position="top-center"
    :expand="false"
    :visible-toasts="3"
    :rich-colors="false"
    :close-button="true"
    close-button-position="top-right"
    :theme="theme"
    data-test="app-toaster"
  />
</template>

<script lang="ts">
import { defineComponent, ref, onMounted, onBeforeUnmount } from 'vue';
import { Toaster } from 'vue-sonner';

export default defineComponent({
  name: 'AppToaster',
  components: { Toaster },
  setup() {
    const theme = ref<'light' | 'dark'>(
      document.body.classList.contains('body--dark') ? 'dark' : 'light',
    );

    let observer: MutationObserver | null = null;

    onMounted(() => {
      observer = new MutationObserver(() => {
        theme.value = document.body.classList.contains('body--dark') ? 'dark' : 'light';
      });
      observer.observe(document.body, { attributes: true, attributeFilter: ['class'] });
    });

    onBeforeUnmount(() => {
      observer?.disconnect();
    });

    return { theme };
  },
});
</script>
